 ('PER_RASTAFARI','Rastafari Era',1930,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BARRETT_RASTAFARIANS','secondary scholarship','Leonard E. Barrett, The Rastafarians (Beacon Press, rev. ed. 1997)','Rastafari history, theology, and social context'),
 ('SRC_EDMONDS_RASTAFARI_VSI','secondary scholarship','Ennis B. Edmonds, Rastafari: A Very Short Introduction (Oxford University Press, 2012)','Rastafari beliefs, key figures, and worldwide spread')
INSERT INTO _e VALUES
 ('ENT_RAS_RASTAFARI','Rastafari','collective','tradition','Rastafari','religious movement','B','Hub collective for the Rastafari movement, a living Abrahamic-derived Jamaican (Caribbean / worldwide) religion founded in the 1930s; publicly attested in scholarship (Barrett; Edmonds).'),
 ('ENT_RAS_JAH','Jah','deity','deity','Rastafari','supreme God','B','The supreme God of Rastafari; the name derives from Jehovah/YHWH and is publicly central to Rastafari practice and reasoning (''I-and-I''). Attested throughout Barrett and Edmonds.'),
 ('ENT_RAS_HAILE_SELASSIE','Haile Selassie I (Ras Tafari Makonnen)','person','venerated figure','Rastafari','venerated emperor / messianic figure','B','Emperor of Ethiopia (1930-1974); venerated by many Rastafari adherents as the returned Christ or as divine. Modeled neutrally as a belief held within the tradition. Publicly attested (Barrett; Edmonds).'),
 ('ENT_RAS_MARCUS_GARVEY','Marcus Garvey','person','prophet','Rastafari','prophet-forerunner','B','Jamaican Pan-Africanist leader (1887-1940) received within Rastafari as a prophet-forerunner who foretold the crowning of an African king. Publicly attested historical figure (Barrett; Edmonds).'),
 ('ENT_RAS_BABYLON','Babylon','concept','concept','Rastafari','oppressive worldly system','B','Rastafari theological concept for the corrupt, oppressive system of Western/colonial society and its institutions, drawn from the biblical Babylon. Publicly attested (Barrett; Edmonds).'),
 ('ENT_RAS_ZION','Zion','concept','concept','Rastafari','promised land','B','Rastafari theological concept of the promised land of redemption and return, identified with Ethiopia/Africa, opposed to Babylon. Publicly attested (Barrett; Edmonds).');
