INSERT INTO _r VALUES
 ('ENT_RAS_JAH','member_of','ENT_RAS_RASTAFARI','high','Jah is the supreme God of the Rastafari movement.'),
 ('ENT_RAS_HAILE_SELASSIE','member_of','ENT_RAS_RASTAFARI','high','Haile Selassie I is the central venerated figure of the Rastafari movement.'),
 ('ENT_RAS_MARCUS_GARVEY','member_of','ENT_RAS_RASTAFARI','high','Marcus Garvey is received within Rastafari as a prophet-forerunner of the movement.'),
 ('ENT_RAS_BABYLON','member_of','ENT_RAS_RASTAFARI','high','Babylon is a core theological concept of the Rastafari movement.'),
 ('ENT_RAS_ZION','member_of','ENT_RAS_RASTAFARI','high','Zion is a core theological concept of the Rastafari movement.'),
 ('ENT_RAS_JAH','reception_of','ENT_ISR_YAHWEH','high','Jah derives from Jehovah, a vocalization of the Tetragrammaton YHWH (Yahweh), received via the King James Bible (Psalm 68:4).'),
 ('ENT_RAS_BABYLON','reception_of','ENT_CHR_WHORE_BABYLON','high','The Rastafari concept of Babylon draws on the biblical Babylon / Whore of Babylon of Revelation as the symbol of corrupt worldly power.'),
 ('ENT_RAS_BABYLON','opposes','ENT_RAS_ZION','high','In Rastafari theology Babylon (the oppressive system) stands in opposition to Zion (the promised land).'),
 ('ENT_RAS_HAILE_SELASSIE','reception_of','ENT_JESUS_CHRIST','high','Many Rastafari adherents venerate Haile Selassie I as the returned Christ; this models that belief held within the tradition as a reception of the figure of Jesus Christ.'),
 ('ENT_RAS_HAILE_SELASSIE','reception_of','ENT_ETH_MENELIK','medium','Haile Selassie''s imperial legitimacy is grounded in the Ethiopian Solomonic dynasty traced to Menelik I, central to Rastafari''s Ethiopianist theology.'),
 ('ENT_ETH_MENELIK','child_of','ENT_ETH_MAKEDA','high','In the Kebra Nagast tradition Menelik I is the son of Makeda, Queen of Sheba; cited within Rastafari to ground the Solomonic line venerated in the movement.');
